        place: 'パリ', lon: 2.35, lat: 48.86, span: 14, polities: ['france', 'england'],
        marks: [{ name: 'ロンドン', lon: -0.12, lat: 51.51 }, { name: 'マルセイユ', lon: 5.37, lat: 43.3 }],
